/* Viewer for the learn site. No build step: plain browser JS.
 *
 * Routes (hash based):
 *   #/                      home (home.md + module grid)
 *   #/<module-slug>         module overview
 *   #/<module-slug>/<file>  chapter
 *
 * Data:
 *   manifest.json                       generated by .claude/skills/add-module/scripts/validate.py
 *   modules/<slug>/<file>.md            chapter with YAML-ish frontmatter
 *
 * Markdown extensions:
 *   :::tabs / == Label / :::            technology switcher, preference shared across pages
 *   > [!NOTE] | [!TIP] | [!WARNING]     callouts
 */
(() => {
  "use strict";

  const PROGRESS_KEY = "learn-progress";
  const TAB_KEY = "learn-tab-pref";
  const THEME_KEY = "learn-theme";

  const $ = (sel, root = document) => root.querySelector(sel);
  const content = $("#content");
  const moduleList = $("#module-list");

  let manifest = null;

  // ---------- storage (never throws) ----------
  const store = {
    get(key, fallback) {
      try {
        const raw = localStorage.getItem(key);
        return raw === null ? fallback : JSON.parse(raw);
      } catch {
        return fallback;
      }
    },
    set(key, value) {
      try {
        localStorage.setItem(key, JSON.stringify(value));
      } catch {
        /* private mode or blocked storage: keep working without persistence */
      }
    },
  };

  const progress = () => store.get(PROGRESS_KEY, {});
  const isDone = (slug, file) => Boolean(progress()[`${slug}/${file}`]);
  function setDone(slug, file, done) {
    const p = progress();
    if (done) p[`${slug}/${file}`] = true;
    else delete p[`${slug}/${file}`];
    store.set(PROGRESS_KEY, p);
    renderSidebar();
    renderGlobalProgress();
  }

  // ---------- theme ----------
  function applyTheme(theme) {
    const root = document.documentElement;
    if (theme) root.dataset.theme = theme;
    else delete root.dataset.theme;
    const dark =
      theme === "dark" ||
      (!theme && window.matchMedia("(prefers-color-scheme: dark)").matches);
    $("#hl-dark").disabled = !dark;
    $("#hl-light").disabled = dark;
  }
  $("#theme-toggle").addEventListener("click", () => {
    const current = document.documentElement.dataset.theme;
    const systemDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
    const isDark = current ? current === "dark" : systemDark;
    const next = isDark ? "light" : "dark";
    store.set(THEME_KEY, next);
    applyTheme(next);
  });
  applyTheme(store.get(THEME_KEY, null));

  // ---------- markdown ----------
  function parseFrontmatter(text) {
    const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?/);
    if (!m) return { meta: {}, body: text };
    const meta = {};
    for (const line of m[1].split(/\r?\n/)) {
      const kv = line.match(/^(\w[\w-]*):\s*(.*)$/);
      if (kv) meta[kv[1]] = kv[2].replace(/\s+#.*$/, "").replace(/^["']|["']$/g, "");
    }
    return { meta, body: text.slice(m[0].length) };
  }

  /* Pull :::tabs blocks out before marked runs, render each tab separately,
   * and leave a placeholder div that is swapped back in afterwards. Fences
   * are tracked so "==" or ":::" inside code blocks are left alone. */
  function extractTabs(md) {
    const lines = md.split("\n");
    const out = [];
    const blocks = [];
    let i = 0;
    while (i < lines.length) {
      if (lines[i].trim() !== ":::tabs") {
        out.push(lines[i]);
        i++;
        continue;
      }
      const tabs = [];
      let current = null;
      let fence = null;
      i++;
      for (; i < lines.length; i++) {
        const line = lines[i];
        const fenceMatch = line.match(/^\s*(`{3,}|~{3,})/);
        if (fenceMatch) {
          if (!fence) fence = fenceMatch[1];
          else if (line.trim().startsWith(fence)) fence = null;
        }
        if (!fence && line.trim() === ":::") break;
        const label = !fence && line.match(/^==\s+(.+?)\s*$/);
        if (label) {
          current = { label: label[1], lines: [] };
          tabs.push(current);
        } else if (current) {
          current.lines.push(line);
        }
      }
      i++; // skip closing :::
      blocks.push(tabs);
      out.push("", `<div data-tabs-placeholder="${blocks.length - 1}"></div>`, "");
    }
    return { md: out.join("\n"), blocks };
  }

  function renderMarkdown(md) {
    const { md: stripped, blocks } = extractTabs(md);
    const html = marked.parse(stripped);
    const wrap = document.createElement("div");
    wrap.innerHTML = html;
    wrap.querySelectorAll("[data-tabs-placeholder]").forEach((ph) => {
      const tabs = blocks[Number(ph.dataset.tabsPlaceholder)];
      ph.replaceWith(buildTabs(tabs));
    });
    decorate(wrap);
    return wrap;
  }

  function buildTabs(tabs) {
    const box = document.createElement("div");
    box.className = "tabs";
    const bar = document.createElement("div");
    bar.className = "tab-bar";
    bar.setAttribute("role", "tablist");
    tabs.forEach((tab, idx) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "tab-btn";
      btn.textContent = tab.label;
      btn.dataset.label = tab.label;
      btn.setAttribute("role", "tab");
      btn.addEventListener("click", () => {
        store.set(TAB_KEY, tab.label);
        syncAllTabs(tab.label);
      });
      bar.appendChild(btn);
      const panel = document.createElement("div");
      panel.className = "tab-panel";
      panel.dataset.label = tab.label;
      panel.setAttribute("role", "tabpanel");
      panel.innerHTML = marked.parse(tab.lines.join("\n"));
      box.appendChild(panel);
      if (idx === 0) box.prepend(bar);
    });
    selectTab(box, store.get(TAB_KEY, null));
    return box;
  }

  function selectTab(box, label) {
    const buttons = [...box.querySelectorAll(":scope > .tab-bar > .tab-btn")];
    const target = buttons.some((b) => b.dataset.label === label)
      ? label
      : buttons[0]?.dataset.label;
    buttons.forEach((b) => {
      const on = b.dataset.label === target;
      b.classList.toggle("active", on);
      b.setAttribute("aria-selected", String(on));
    });
    box.querySelectorAll(":scope > .tab-panel").forEach((p) => {
      p.hidden = p.dataset.label !== target;
    });
  }

  function syncAllTabs(label) {
    document.querySelectorAll(".tabs").forEach((box) => selectTab(box, label));
  }

  function decorate(root) {
    // syntax highlight + copy buttons
    root.querySelectorAll("pre > code").forEach((code) => {
      try {
        hljs.highlightElement(code);
      } catch {
        /* unknown language: leave plain */
      }
      const pre = code.parentElement;
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "copy-btn";
      btn.textContent = "copiar";
      btn.addEventListener("click", async () => {
        try {
          await navigator.clipboard.writeText(code.innerText);
          btn.textContent = "copiado";
        } catch {
          btn.textContent = "error";
        }
        setTimeout(() => (btn.textContent = "copiar"), 1200);
      });
      pre.appendChild(btn);
    });
    // callouts: > [!NOTE] ...
    root.querySelectorAll("blockquote").forEach((bq) => {
      const first = bq.querySelector("p");
      const m = first && first.innerHTML.match(/^\[!(NOTE|TIP|WARNING|IMPORTANT)\]\s*(<br>)?/i);
      if (!m) return;
      const kind = m[1].toLowerCase();
      first.innerHTML = first.innerHTML.slice(m[0].length);
      bq.classList.add("callout", `callout-${kind}`);
      const title = document.createElement("div");
      title.className = "callout-title";
      title.textContent = { note: "Nota", tip: "Tip", warning: "Cuidado", important: "Importante" }[kind];
      bq.prepend(title);
    });
    // external links open in new tab
    root.querySelectorAll('a[href^="http"]').forEach((a) => {
      a.target = "_blank";
      a.rel = "noopener";
    });
  }

  // ---------- data ----------
  async function fetchText(url) {
    const res = await fetch(url, { cache: "no-cache" });
    if (!res.ok) throw new Error(`${res.status} al cargar ${url}`);
    return res.text();
  }

  const findModule = (slug) => manifest.modules.find((m) => m.slug === slug);

  // ---------- sidebar ----------
  function moduleProgress(mod) {
    const total = mod.chapters.length;
    const done = mod.chapters.filter((c) => isDone(mod.slug, c.file)).length;
    return { total, done, pct: total ? Math.round((done / total) * 100) : 0 };
  }

  function renderSidebar() {
    if (!manifest) return;
    const filter = $("#search").value.trim().toLowerCase();
    const route = parseRoute();
    moduleList.innerHTML = "";
    for (const mod of manifest.modules) {
      const chapters = mod.chapters.filter(
        (c) => !filter || c.title.toLowerCase().includes(filter) || mod.title.toLowerCase().includes(filter)
      );
      if (filter && !chapters.length) continue;
      const li = document.createElement("li");
      li.className = "mod";
      if (route.slug === mod.slug) li.classList.add("open");
      const { done, total, pct } = moduleProgress(mod);
      const head = document.createElement("a");
      head.className = "mod-head";
      head.href = `#/${mod.slug}`;
      head.innerHTML = `<span class="mod-num">${String(mod.order).padStart(2, "0")}</span>
        <span class="mod-title"></span>
        <span class="mod-meta">${mod.status === "pending" ? "pendiente" : `${done}/${total}`}</span>
        <span class="bar"><span style="width:${pct}%"></span></span>`;
      $(".mod-title", head).textContent = mod.title;
      if (mod.status === "pending") head.classList.add("pending");
      if (route.slug === mod.slug && !route.file) head.classList.add("active");
      li.appendChild(head);
      if (chapters.length && (filter || route.slug === mod.slug)) {
        const ul = document.createElement("ul");
        for (const ch of chapters) {
          const cli = document.createElement("li");
          const a = document.createElement("a");
          a.href = `#/${mod.slug}/${ch.file}`;
          a.className = "chap";
          if (route.slug === mod.slug && route.file === ch.file) a.classList.add("active");
          const box = document.createElement("input");
          box.type = "checkbox";
          box.checked = isDone(mod.slug, ch.file);
          box.title = "Marcar como leído";
          box.addEventListener("click", (e) => {
            e.stopPropagation();
            setDone(mod.slug, ch.file, box.checked);
          });
          const span = document.createElement("span");
          span.textContent = ch.title;
          a.append(box, span);
          cli.appendChild(a);
          ul.appendChild(cli);
        }
        li.appendChild(ul);
      }
      moduleList.appendChild(li);
    }
  }

  function renderGlobalProgress() {
    if (!manifest) return;
    let total = 0;
    let done = 0;
    for (const mod of manifest.modules) {
      const p = moduleProgress(mod);
      total += p.total;
      done += p.done;
    }
    $("#global-progress").textContent = total ? `${done}/${total} capítulos` : "";
  }

  $("#search").addEventListener("input", renderSidebar);
  $("#menu-toggle").addEventListener("click", () => document.body.classList.toggle("nav-open"));

  // ---------- views ----------
  function parseRoute() {
    const parts = location.hash.replace(/^#\/?/, "").split("/").filter(Boolean).map(decodeURIComponent);
    return { slug: parts[0] || null, file: parts[1] || null };
  }

  function chips(items, cls = "chip") {
    return items.map((t) => `<span class="${cls}">${escapeHtml(t)}</span>`).join("");
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
  }

  function moduleHeader(mod) {
    const versions = Object.entries(mod.versions || {});
    const prereqs = (mod.prereqs || [])
      .map((slug) => {
        const p = findModule(slug);
        return p ? `<a href="#/${p.slug}">${escapeHtml(p.title)}</a>` : escapeHtml(slug);
      })
      .join(", ");
    return `<div class="mod-header">
      <div class="eyebrow">Módulo ${String(mod.order).padStart(2, "0")} · ${escapeHtml(mod.level || "")}</div>
      <h1>${escapeHtml(mod.title)}</h1>
      <p class="lead">${escapeHtml(mod.summary || "")}</p>
      <div class="meta-row">${chips(mod.tags || [])}</div>
      ${prereqs ? `<div class="meta-line"><strong>Antes:</strong> ${prereqs}</div>` : ""}
      ${
        versions.length
          ? `<div class="meta-line"><strong>Versiones:</strong> ${versions
              .map(([k, v]) => `<code>${escapeHtml(k)}==${escapeHtml(v)}</code>`)
              .join(" ")}</div>`
          : ""
      }
    </div>`;
  }

  async function renderHome() {
    document.title = "Learn: AI Engineer";
    let homeHtml = "";
    try {
      homeHtml = renderMarkdown(parseFrontmatter(await fetchText("home.md")).body).innerHTML;
    } catch {
      homeHtml = "<h1>Learn: AI Engineer</h1>";
    }
    const cards = manifest.modules
      .map((m) => {
        const { done, total, pct } = moduleProgress(m);
        return `<a class="card ${m.status === "pending" ? "pending" : ""}" href="#/${m.slug}">
          <div class="eyebrow">${String(m.order).padStart(2, "0")} · ${escapeHtml(m.level || "")}</div>
          <h3>${escapeHtml(m.title)}</h3>
          <p>${escapeHtml(m.summary || "")}</p>
          <div class="card-foot">${m.status === "pending" ? "pendiente" : `${done}/${total} capítulos`}
            <span class="bar"><span style="width:${pct}%"></span></span></div>
        </a>`;
      })
      .join("");
    content.innerHTML = `<article class="prose">${homeHtml}</article><div class="cards">${cards}</div>`;
  }

  function renderModule(mod) {
    document.title = `${mod.title} · learn`;
    let body;
    if (mod.status === "pending") {
      const planned = (mod.planned_chapters || []).map((t) => `<li>${escapeHtml(t)}</li>`).join("");
      body = `<div class="pending-box">
        <p>Este módulo todavía no tiene contenido. Generalo desde Claude Code:</p>
        <pre><code>/add-module ${escapeHtml(mod.slug.replace(/^\d+-/, ""))}</code></pre>
        ${planned ? `<p>Capítulos planificados:</p><ol>${planned}</ol>` : ""}
      </div>`;
    } else {
      const items = mod.chapters
        .map(
          (c) => `<li><a href="#/${mod.slug}/${c.file}">
            <span class="check">${isDone(mod.slug, c.file) ? "✓" : ""}</span>
            <span>${escapeHtml(c.title)}</span>
            <span class="type type-${escapeHtml(c.type)}">${escapeHtml(c.type)}</span></a></li>`
        )
        .join("");
      body = `<ol class="toc">${items}</ol>`;
    }
    content.innerHTML = `<article class="prose">${moduleHeader(mod)}${body}</article>`;
  }

  async function renderChapter(mod, file) {
    const idx = mod.chapters.findIndex((c) => c.file === file);
    if (idx === -1) return renderNotFound();
    const chapter = mod.chapters[idx];
    document.title = `${chapter.title} · ${mod.title}`;
    content.innerHTML = `<p class="loading">Cargando…</p>`;
    const raw = await fetchText(`modules/${mod.slug}/${file}`);
    const { body } = parseFrontmatter(raw);
    const article = document.createElement("article");
    article.className = "prose";
    article.innerHTML = `<div class="crumbs"><a href="#/${mod.slug}">${escapeHtml(mod.title)}</a> · capítulo ${idx + 1} de ${mod.chapters.length}</div>
      <h1>${escapeHtml(chapter.title)}</h1>`;
    article.append(...renderMarkdown(body).childNodes);

    const prev = mod.chapters[idx - 1];
    const next = mod.chapters[idx + 1];
    const done = isDone(mod.slug, file);
    const foot = document.createElement("div");
    foot.className = "chapter-foot";
    foot.innerHTML = `
      ${prev ? `<a class="nav prev" href="#/${mod.slug}/${prev.file}">← ${escapeHtml(prev.title)}</a>` : "<span></span>"}
      <button type="button" class="done-btn ${done ? "is-done" : ""}">${done ? "✓ Leído" : "Marcar como leído"}</button>
      ${next ? `<a class="nav next" href="#/${mod.slug}/${next.file}">${escapeHtml(next.title)} →</a>` : "<span></span>"}`;
    $(".done-btn", foot).addEventListener("click", () => {
      setDone(mod.slug, file, !isDone(mod.slug, file));
      if (isDone(mod.slug, file) && next) location.hash = `#/${mod.slug}/${next.file}`;
      else render();
    });
    article.appendChild(foot);
    content.innerHTML = "";
    content.appendChild(article);
  }

  function renderNotFound() {
    content.innerHTML = `<article class="prose"><h1>No encontrado</h1><p><a href="#/">Volver al inicio</a></p></article>`;
  }

  function renderError(err) {
    const fileHint =
      location.protocol === "file:"
        ? `<p>Estás abriendo el archivo directo. Serví el sitio con <code>./serve.sh</code> y entrá a <code>http://localhost:8787</code>.</p>`
        : "";
    content.innerHTML = `<article class="prose"><h1>Error</h1><p>${escapeHtml(err.message)}</p>${fileHint}</article>`;
  }

  async function render() {
    document.body.classList.remove("nav-open");
    renderSidebar();
    const { slug, file } = parseRoute();
    try {
      if (!slug) await renderHome();
      else {
        const mod = findModule(slug);
        if (!mod) renderNotFound();
        else if (!file) renderModule(mod);
        else await renderChapter(mod, file);
      }
    } catch (err) {
      renderError(err);
    }
    window.scrollTo(0, 0);
    content.focus({ preventScroll: true });
  }

  async function init() {
    marked.setOptions({ gfm: true });
    try {
      manifest = JSON.parse(await fetchText("manifest.json"));
      manifest.modules.sort((a, b) => a.order - b.order);
    } catch (err) {
      renderError(err);
      return;
    }
    renderGlobalProgress();
    window.addEventListener("hashchange", render);
    render();
  }

  init();
})();
